import { sql } from "drizzle-orm";
import { check, index, integer, primaryKey, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";

/**
 * Lumo SQLite schema (see docs/ARCHITECTURE.md, "Data model").
 *
 * - Identifiers: text UUIDs generated by the application.
 * - Horodatages : entiers en millisecondes Unix (UTC).
 * - `local_date`: `YYYY-MM-DD` text in the household time zone.
 * - No stored balance: a balance is the sum of a wallet's `ledger_entries`.
 */

const id = () => text("id").primaryKey();
const ts = (name: string) => integer(name, { mode: "timestamp_ms" });
const createdAt = () => ts("created_at").notNull().default(sql`(unixepoch('subsec') * 1000)`);

export const ROLES = ["owner", "member"] as const;
export const ITEM_KINDS = ["habit", "task"] as const;
export const WALLET_KINDS = ["personal", "shared"] as const;
export const COMPLETION_STATUSES = ["pending", "approved", "rejected"] as const;
export const LEDGER_REASONS = ["completion", "undo", "redemption", "transfer", "adjustment"] as const;
export const LIMIT_PERIODS = ["day", "week", "month", "year"] as const;
export const SESSION_KINDS = ["web", "mobile"] as const;
export const GUARDIANSHIP_CODE_KINDS = ["supervise", "be_supervised"] as const;
export const PLATFORMS = ["android", "ios"] as const;

const inList = (column: string, values: readonly string[]) =>
	sql.raw(`${column} IN (${values.map((v) => `'${v}'`).join(", ")})`);

export const households = sqliteTable(
	"households",
	{
		id: id(),
		name: text("name").notNull(),
		backdateDays: integer("backdate_days").notNull().default(2),
		/** When true there is no backdate limit (`backdate_days` keeps its last value, for when it is turned back on). */
		backdateUnlimited: integer("backdate_unlimited", { mode: "boolean" }).notNull().default(false),
		createdAt: createdAt(),
	},
	(t) => [check("households_backdate_days_check", sql`${t.backdateDays} >= 0`)],
);

export const users = sqliteTable(
	"users",
	{
		id: id(),
		displayName: text("display_name").notNull(),
		avatarUrl: text("avatar_url"),
		/** Authentik `sub`; null for a purely local account. */
		oidcSubject: text("oidc_subject"),
		/** Local account (fallback): sign-in username, lowercase. */
		username: text("username"),
		email: text("email"),
		/** Argon2id hash; null for an OIDC-only account. */
		passwordHash: text("password_hash"),
		/** Time zone and first weekday of the person: nobody has two "todays", whatever households they belong to. */
		timezone: text("timezone").notNull().default("UTC"),
		weekStart: integer("week_start").notNull().default(1),
		/** Instance-level role: manages accounts and households, sees no content. */
		isSuperAdmin: integer("is_super_admin", { mode: "boolean" }).notNull().default(false),
		/** What guardians allow this account to do by itself; ignored while it has no guardian. */
		canCreate: integer("can_create", { mode: "boolean" }).notNull().default(false),
		canModify: integer("can_modify", { mode: "boolean" }).notNull().default(false),
		canDelete: integer("can_delete", { mode: "boolean" }).notNull().default(false),
		canTransfer: integer("can_transfer", { mode: "boolean" }).notNull().default(true),
		/** A disabled account cannot sign in; its data is kept. */
		disabledAt: ts("disabled_at"),
		/** A deleted account has no credentials left; the row stays so history keeps a name. */
		deletedAt: ts("deleted_at"),
		createdAt: createdAt(),
	},
	(t) => [
		uniqueIndex("users_oidc_subject_uq").on(t.oidcSubject),
		uniqueIndex("users_username_uq").on(t.username),
		uniqueIndex("users_email_uq").on(t.email),
	],
);

export const memberships = sqliteTable(
	"memberships",
	{
		householdId: text("household_id")
			.notNull()
			.references(() => households.id, { onDelete: "cascade" }),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		role: text("role", { enum: ROLES }).notNull(),
		createdAt: createdAt(),
	},
	(t) => [
		primaryKey({ columns: [t.householdId, t.userId] }),
		index("memberships_user_idx").on(t.userId),
		check("memberships_role_check", inList(t.role.name, ROLES)),
	],
);

export const wallets = sqliteTable(
	"wallets",
	{
		id: id(),
		/** The household pot only; a personal wallet belongs to the account, whatever households it joins. */
		householdId: text("household_id").references(() => households.id, { onDelete: "cascade" }),
		kind: text("kind", { enum: WALLET_KINDS }).notNull(),
		/** Null for the household pot. */
		userId: text("user_id").references(() => users.id, { onDelete: "cascade" }),
		createdAt: createdAt(),
	},
	(t) => [
		uniqueIndex("wallets_personal_uq").on(t.userId).where(sql`${t.kind} = 'personal'`),
		uniqueIndex("wallets_shared_uq").on(t.householdId).where(sql`${t.kind} = 'shared'`),
		check("wallets_kind_check", inList(t.kind.name, WALLET_KINDS)),
		check(
			"wallets_user_check",
			sql`(${t.kind} = 'personal' AND ${t.userId} IS NOT NULL AND ${t.householdId} IS NULL) OR (${t.kind} = 'shared' AND ${t.userId} IS NULL AND ${t.householdId} IS NOT NULL)`,
		),
	],
);

export const items = sqliteTable(
	"items",
	{
		id: id(),
		/** Exactly one of `householdId` (shared with a household) and `ownerId` (personal) is set. */
		householdId: text("household_id").references(() => households.id, { onDelete: "cascade" }),
		ownerId: text("owner_id").references(() => users.id, { onDelete: "cascade" }),
		kind: text("kind", { enum: ITEM_KINDS }).notNull(),
		name: text("name").notNull(),
		description: text("description"),
		/** Schedule validated by Zod in `domain`: daily, weekly, timesPerWeek, monthly. Null for a task. */
		schedule: text("schedule", { mode: "json" }),
		targetPerPeriod: integer("target_per_period").notNull().default(1),
		reward: integer("reward").notNull().default(0),
		creditsTo: text("credits_to", { enum: WALLET_KINDS }).notNull().default("personal"),
		dueAt: ts("due_at"),
		pinned: integer("pinned", { mode: "boolean" }).notNull().default(false),
		requiresApproval: integer("requires_approval", { mode: "boolean" }).notNull().default(false),
		archivedAt: ts("archived_at"),
		createdBy: text("created_by")
			.notNull()
			.references(() => users.id),
		createdAt: createdAt(),
	},
	(t) => [
		index("items_household_idx").on(t.householdId, t.archivedAt),
		index("items_owner_idx").on(t.ownerId, t.archivedAt),
		check("items_scope_check", sql`(${t.householdId} IS NULL) <> (${t.ownerId} IS NULL)`),
		check("items_kind_check", inList(t.kind.name, ITEM_KINDS)),
		check("items_credits_to_check", inList(t.creditsTo.name, WALLET_KINDS)),
		check("items_target_check", sql`${t.targetPerPeriod} >= 1`),
		check("items_reward_check", sql`${t.reward} >= 0`),
	],
);

export const itemAssignees = sqliteTable(
	"item_assignees",
	{
		itemId: text("item_id")
			.notNull()
			.references(() => items.id, { onDelete: "cascade" }),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
	},
	(t) => [primaryKey({ columns: [t.itemId, t.userId] }), index("item_assignees_user_idx").on(t.userId)],
);

export const ledgerEntries = sqliteTable(
	"ledger_entries",
	{
		id: id(),
		/** Household the entry is about, if any (personal coins earned on a personal item have none). */
		householdId: text("household_id").references(() => households.id, { onDelete: "cascade" }),
		walletId: text("wallet_id")
			.notNull()
			.references(() => wallets.id),
		/** Signed integer, in coins. */
		amount: integer("amount").notNull(),
		reason: text("reason", { enum: LEDGER_REASONS }).notNull(),
		/** Completion, redemption… that caused the entry. */
		refId: text("ref_id"),
		/** Links the two entries of a transfer. */
		transferId: text("transfer_id"),
		note: text("note"),
		createdBy: text("created_by")
			.notNull()
			.references(() => users.id),
		createdAt: createdAt(),
	},
	(t) => [
		index("ledger_entries_wallet_created_idx").on(t.walletId, t.createdAt),
		index("ledger_entries_transfer_idx").on(t.transferId),
		check("ledger_entries_reason_check", inList(t.reason.name, LEDGER_REASONS)),
		check("ledger_entries_amount_check", sql`${t.amount} <> 0`),
	],
);

export const completions = sqliteTable(
	"completions",
	{
		id: id(),
		itemId: text("item_id")
			.notNull()
			.references(() => items.id, { onDelete: "cascade" }),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		localDate: text("local_date").notNull(),
		status: text("status", { enum: COMPLETION_STATUSES }).notNull().default("approved"),
		approvedBy: text("approved_by").references(() => users.id),
		completedAt: ts("completed_at").notNull(),
		/** Undoing sets `undone_at`; the row is never deleted. */
		undoneAt: ts("undone_at"),
		ledgerEntryId: text("ledger_entry_id").references(() => ledgerEntries.id),
	},
	(t) => [
		index("completions_item_user_date_idx").on(t.itemId, t.userId, t.localDate),
		check("completions_status_check", inList(t.status.name, COMPLETION_STATUSES)),
		check("completions_local_date_check", sql`${t.localDate} GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'`),
	],
);

export const rewards = sqliteTable(
	"rewards",
	{
		id: id(),
		/** Exactly one of `householdId` and `ownerId` is set. */
		householdId: text("household_id").references(() => households.id, { onDelete: "cascade" }),
		ownerId: text("owner_id").references(() => users.id, { onDelete: "cascade" }),
		name: text("name").notNull(),
		description: text("description"),
		cost: integer("cost").notNull(),
		fundedFrom: text("funded_from", { enum: WALLET_KINDS }).notNull().default("personal"),
		limitCount: integer("limit_count"),
		limitPeriod: text("limit_period", { enum: LIMIT_PERIODS }),
		link: text("link"),
		archivedAt: ts("archived_at"),
		createdAt: createdAt(),
	},
	(t) => [
		index("rewards_household_idx").on(t.householdId, t.archivedAt),
		index("rewards_owner_idx").on(t.ownerId, t.archivedAt),
		check("rewards_scope_check", sql`(${t.householdId} IS NULL) <> (${t.ownerId} IS NULL)`),
		check("rewards_cost_check", sql`${t.cost} >= 0`),
		check("rewards_funded_from_check", inList(t.fundedFrom.name, WALLET_KINDS)),
		check(
			"rewards_limit_check",
			sql`(${t.limitCount} IS NULL AND ${t.limitPeriod} IS NULL) OR (${t.limitCount} >= 1 AND ${t.limitPeriod} IN ('day', 'week', 'month', 'year'))`,
		),
	],
);

export const rewardAssignees = sqliteTable(
	"reward_assignees",
	{
		rewardId: text("reward_id")
			.notNull()
			.references(() => rewards.id, { onDelete: "cascade" }),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
	},
	(t) => [primaryKey({ columns: [t.rewardId, t.userId] })],
);

export const redemptions = sqliteTable(
	"redemptions",
	{
		id: id(),
		rewardId: text("reward_id")
			.notNull()
			.references(() => rewards.id),
		userId: text("user_id")
			.notNull()
			.references(() => users.id),
		walletId: text("wallet_id")
			.notNull()
			.references(() => wallets.id),
		redeemedAt: ts("redeemed_at").notNull(),
		/** Undoing sets `undone_at`; the row is never deleted and the refund is a counter-entry. */
		undoneAt: ts("undone_at"),
		ledgerEntryId: text("ledger_entry_id")
			.notNull()
			.references(() => ledgerEntries.id),
	},
	(t) => [index("redemptions_reward_user_idx").on(t.rewardId, t.userId, t.redeemedAt)],
);

export const devices = sqliteTable(
	"devices",
	{
		id: id(),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		pushToken: text("push_token").notNull(),
		platform: text("platform", { enum: PLATFORMS }).notNull(),
		lastSeenAt: ts("last_seen_at").notNull(),
	},
	(t) => [
		uniqueIndex("devices_push_token_uq").on(t.pushToken),
		index("devices_user_idx").on(t.userId),
		check("devices_platform_check", inList(t.platform.name, PLATFORMS)),
	],
);

/**
 * Sessions: web cookie (`kind = 'web'`) or mobile refresh token (`kind = 'mobile'`).
 * The plain token is never stored, only its SHA-256 hash.
 * `previous_token_hash` detects reuse of a refresh token that was already rotated.
 */
export const sessions = sqliteTable(
	"sessions",
	{
		id: id(),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		kind: text("kind", { enum: SESSION_KINDS }).notNull(),
		refreshTokenHash: text("refresh_token_hash").notNull(),
		previousTokenHash: text("previous_token_hash"),
		expiresAt: ts("expires_at").notNull(),
		deviceId: text("device_id").references(() => devices.id, { onDelete: "set null" }),
		createdAt: createdAt(),
		lastUsedAt: ts("last_used_at").notNull(),
	},
	(t) => [
		uniqueIndex("sessions_token_hash_uq").on(t.refreshTokenHash),
		index("sessions_user_idx").on(t.userId),
		index("sessions_expires_idx").on(t.expiresAt),
		check("sessions_kind_check", inList(t.kind.name, SESSION_KINDS)),
	],
);

export const idempotencyKeys = sqliteTable(
	"idempotency_keys",
	{
		key: text("key").notNull(),
		userId: text("user_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		/** Response already returned (status + JSON body). */
		response: text("response", { mode: "json" }).notNull(),
		createdAt: createdAt(),
	},
	(t) => [primaryKey({ columns: [t.userId, t.key] }), index("idempotency_keys_created_idx").on(t.createdAt)],
);

/** Invitations: the only way to create an account (apart from the very first user). */
export const invites = sqliteTable(
	"invites",
	{
		id: id(),
		householdId: text("household_id")
			.notNull()
			.references(() => households.id, { onDelete: "cascade" }),
		tokenHash: text("token_hash").notNull(),
		role: text("role", { enum: ROLES }).notNull(),
		createdBy: text("created_by")
			.notNull()
			.references(() => users.id),
		expiresAt: ts("expires_at").notNull(),
		usedAt: ts("used_at"),
		usedBy: text("used_by").references(() => users.id),
		createdAt: createdAt(),
	},
	(t) => [
		uniqueIndex("invites_token_hash_uq").on(t.tokenHash),
		check("invites_role_check", inList(t.role.name, ROLES)),
	],
);

/** `guardian_id` supervises `ward_id`: an account is supervised if and only if it has at least one row. */
export const guardianships = sqliteTable(
	"guardianships",
	{
		id: id(),
		guardianId: text("guardian_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		wardId: text("ward_id")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		createdAt: createdAt(),
	},
	(t) => [
		uniqueIndex("guardianships_pair_uq").on(t.guardianId, t.wardId),
		index("guardianships_ward_idx").on(t.wardId),
		check("guardianships_distinct_check", sql`${t.guardianId} <> ${t.wardId}`),
	],
);

/**
 * One-time code that starts a supervision by mutual consent. `supervise`: made by the guardian, whoever redeems it
 * becomes their ward. `be_supervised`: made by the ward, whoever redeems it becomes their guardian.
 */
export const guardianshipCodes = sqliteTable(
	"guardianship_codes",
	{
		id: id(),
		tokenHash: text("token_hash").notNull(),
		kind: text("kind", { enum: GUARDIANSHIP_CODE_KINDS }).notNull(),
		createdBy: text("created_by")
			.notNull()
			.references(() => users.id, { onDelete: "cascade" }),
		expiresAt: ts("expires_at").notNull(),
		usedAt: ts("used_at"),
		usedBy: text("used_by").references(() => users.id),
		createdAt: createdAt(),
	},
	(t) => [
		uniqueIndex("guardianship_codes_token_hash_uq").on(t.tokenHash),
		check("guardianship_codes_kind_check", inList(t.kind.name, GUARDIANSHIP_CODE_KINDS)),
	],
);

/** Temporary state of a web OIDC sign-in (PKCE + state + nonce). Purged on use or expiry. */
export const oidcStates = sqliteTable(
	"oidc_states",
	{
		state: text("state").primaryKey(),
		nonce: text("nonce").notNull(),
		codeVerifier: text("code_verifier").notNull(),
		/** Plain invitation token, present when the sign-in creates an account. */
		inviteToken: text("invite_token"),
		expiresAt: ts("expires_at").notNull(),
	},
	(t) => [index("oidc_states_expires_idx").on(t.expiresAt)],
);

/** Instance-wide settings edited by super admins (key/value). */
export const instanceSettings = sqliteTable("instance_settings", {
	key: text("key").primaryKey(),
	value: text("value").notNull(),
});
